/**
 * The corpus: `docs/sat-md`, as generated by `pnpm --filter @codice/api
 * sat:knowledge`. The guides become one search passage per section, the RMF one per regla and the
 * CFF one per article (`sections.ts`); every `CFDI40xxx` row of the error matrix becomes a passage too, so a
 * plain-language question finds its code. The matrix and the catalogs also become D1 records for
 * exact lookups. Pure: `ingest.ts` does the I/O.
 */
import { createHash } from "node:crypto";

import { dateNumber, IN_FORCE_UNTIL, isoDate } from "../src/search";
import { buildSatLibrary, type SatDocument, type SatSourceManifest } from "./sat-documents";
import {
  catalogEntryFields,
  catalogEntryKey,
  type SatCatalogSet,
  type SatErrorMatrix,
  type SatSource,
} from "./sat-records";
import { guideSections, lawArticles, nameVocabulary, rmfReglas } from "./sections";

/** AI Search's limit on an item key. */
export const ITEM_KEY_MAX = 128;

export type Passage = {
  /** The AI Search item key, `<source>/<anchor>.md`. */
  readonly key: string;
  readonly sourceId: string;
  readonly heading: string;
  /** What is uploaded: the heading path, then the passage verbatim. */
  readonly body: string;
  readonly sha256: string;
  readonly metadata: {
    readonly authority: string;
    readonly kind: string;
    readonly valid_from: number;
    readonly valid_until: number;
  };
};

export type SourceRow = {
  readonly id: string;
  readonly title: string;
  readonly authority: string;
  readonly url: string;
  readonly sha256: string;
  readonly publishedAt: string | null;
  readonly retrievedAt: string;
  readonly validFrom: number;
  readonly validUntil: number;
};

export type ErrorCodeRow = {
  readonly code: string;
  readonly sourceId: string;
  readonly node: string;
  readonly attribute: string;
  readonly validation: string;
  readonly message: string;
};

export type CatalogEntryRow = {
  readonly catalog: string;
  readonly key: string;
  readonly sourceId: string;
  readonly fields: Record<string, string>;
  readonly validFrom: number;
  readonly validUntil: number;
};

export type Corpus = {
  readonly sources: readonly SourceRow[];
  readonly passages: readonly Passage[];
  readonly errorCodes: readonly ErrorCodeRow[];
  readonly catalogEntries: readonly CatalogEntryRow[];
};

export type SatMarkdownFiles = {
  /** A file of `docs/sat-md` by name. */
  readonly read: (file: string) => string;
};

/** Each `docs/sat-md` source: its Códice id (the passages' folder), kind and authority. */
const SOURCES = {
  anexo20: { id: "anexo-20-guia-de-llenado", kind: "guia", authority: "SAT" },
  pagos: { id: "complemento-pagos-guia-de-llenado", kind: "guia", authority: "SAT" },
  matrix: { id: "matriz-de-errores-cfdi-40", kind: "anexo", authority: "SAT" },
  catalogs: { id: "catalogos-cfdi-40", kind: "anexo", authority: "SAT" },
  rmf: { id: "rmf-2026", kind: "regla", authority: "SAT" },
  cff: { id: "cff", kind: "ley", authority: "Congreso" },
} as const satisfies Record<
  keyof SatSourceManifest,
  { id: string; kind: string; authority: string }
>;

/** The catCFDI source: the small catalogs' and the large ones' (`large-catalogs.ts`). */
export const CATALOG_SOURCE_ID = SOURCES.catalogs.id;

export function sha256(text: string) {
  return createHash("sha256").update(text).digest("hex");
}

/** `Nodo: Receptor › UsoCFDI` → `nodo-receptor-usocfdi`. */
export function anchorOf(label: string, maxLength: number) {
  const slug = label
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase()
    .replaceAll(/[^a-z0-9]+/gu, "-")
    .replaceAll(/^-|-$/gu, "");
  return (slug.slice(0, maxLength).replace(/-$/u, "") || "seccion").slice(0, maxLength);
}

/** The first day a source's text applies: its publication date, else the day it was fetched. */
function sourceValidFrom(source: SatSource) {
  return dateNumber(source.publishedAt ?? source.retrievedAt);
}

function sourceRow(id: keyof SatSourceManifest, title: string, source: SatSource): SourceRow {
  return {
    id: SOURCES[id].id,
    title,
    authority: SOURCES[id].authority,
    url: source.url,
    sha256: source.sha256,
    publishedAt: source.publishedAt,
    retrievedAt: source.retrievedAt,
    validFrom: sourceValidFrom(source),
    validUntil: IN_FORCE_UNTIL,
  };
}

function passage(input: {
  readonly sourceId: string;
  readonly anchor: string;
  readonly heading: string;
  readonly text: string;
  readonly kind: string;
  readonly authority: string;
  readonly validFrom: number;
}): Passage {
  const body = `# ${input.heading}\n\n${input.text.trim()}\n`;
  return {
    key: `${input.sourceId}/${input.anchor}.md`,
    sourceId: input.sourceId,
    heading: input.heading,
    body,
    sha256: sha256(body),
    metadata: {
      authority: input.authority,
      kind: input.kind,
      valid_from: input.validFrom,
      valid_until: IN_FORCE_UNTIL,
    },
  };
}

/** The guide's own (Spanish) title: its Markdown `#` heading. */
export function guideTitle(document: SatDocument) {
  const title = /^# (.+)$/mu.exec(document.markdown)?.[1]?.trim();
  if (!title) throw new Error(`SAT document ${document.slug} has no title`);
  return title;
}

/**
 * One passage a section; an anchor that repeats (a section cut in parts, a node both parts of a
 * guide have) takes `-2`, `-3`, ….
 */
export function guidePassages(
  document: SatDocument,
  sourceId: string,
  validFrom: number,
  vocabulary: ReadonlySet<string>,
): Passage[] {
  const title = guideTitle(document);
  // `<source>/` + anchor + an optional `-NNN` + a superseded version's `.YYYYMMDD` + `.md`.
  const anchorMax = ITEM_KEY_MAX - sourceId.length - 1 - 4 - 9 - 3;
  const seen = new Map<string, number>();
  return guideSections(document.markdown, { title, vocabulary }).map((section) => {
    const base = anchorOf(section.anchor, anchorMax);
    const count = (seen.get(base) ?? 0) + 1;
    seen.set(base, count);
    const heading = section.label === title ? title : `${title} › ${section.label}`;
    return passage({
      sourceId,
      anchor: count === 1 ? base : `${base}-${count}`,
      heading,
      text: section.text,
      kind: "guia",
      authority: "SAT",
      validFrom,
    });
  });
}

/**
 * One passage a regla of the RMF (`rmf-2026/regla-2.7.1.21.md`), valid from the DOF date of the
 * version the SAT's compilation holds.
 */
export function rmfPassages(document: SatDocument): Passage[] {
  const title = guideTitle(document);
  return rmfReglas(document.markdown).map((regla) =>
    passage({
      sourceId: SOURCES.rmf.id,
      anchor: `regla-${regla.number}`,
      heading: `${title} › ${regla.label}`,
      text: regla.text,
      kind: SOURCES.rmf.kind,
      authority: SOURCES.rmf.authority,
      validFrom: dateNumber(regla.publishedAt),
    }),
  );
}

/**
 * One passage an article of the CFF (`cff/articulo-29-a.md`), valid from the law's last reform:
 * the Cámara notes only the reforms since 2021 on each part, so an article's own date is not known.
 */
export function cffPassages(document: SatDocument, validFrom: number): Passage[] {
  const title = guideTitle(document);
  return lawArticles(document.markdown).map((article) =>
    passage({
      sourceId: SOURCES.cff.id,
      anchor: `articulo-${anchorOf(article.number, ITEM_KEY_MAX)}`,
      heading: `${title} › ${article.label}`,
      text: article.text,
      kind: SOURCES.cff.kind,
      authority: SOURCES.cff.authority,
      validFrom,
    }),
  );
}

/** One passage a matrix row: the SAT's validation and message, verbatim, under its node. */
export function errorCodePassages(matrix: SatErrorMatrix): Passage[] {
  const sourceId = SOURCES.matrix.id;
  return matrix.codes.map((row) =>
    passage({
      sourceId,
      anchor: anchorOf(row.code, ITEM_KEY_MAX),
      heading: `${matrix.title} › ${row.element} › ${row.attribute} › ${row.code}`,
      text: [
        `Código: ${row.code}`,
        `Nodo: ${row.element}`,
        `Atributo: ${row.attribute}`,
        `Validación: ${row.validation}`,
        `Mensaje: ${row.message}`,
      ].join("\n\n"),
      kind: SOURCES.matrix.kind,
      authority: SOURCES.matrix.authority,
      validFrom: sourceValidFrom(matrix.source),
    }),
  );
}

function columnIndex(columns: readonly string[], pattern: RegExp) {
  return columns.findIndex((column) => pattern.test(column));
}

/** Catalog rows as entries; a row's own validity columns win over the catalog's. */
export function catalogEntryRows(set: SatCatalogSet): CatalogEntryRow[] {
  const sourceId = SOURCES.catalogs.id;
  return set.catalogs.flatMap((catalog) => {
    const from = columnIndex(catalog.columns, /inicio\s*(?:de\s*)?vigencia/iu);
    const until = columnIndex(catalog.columns, /fin\s*(?:de\s*)?vigencia/iu);
    const catalogFrom =
      catalog.version["Fecha inicio de vigencia del catálogo"] ??
      set.source.publishedAt ??
      set.source.retrievedAt;
    return catalog.rows.map((row) => {
      const date = (value: string) => {
        // A whole ISO date that exists: `2026-02-31` or `2026-07-31x` is refused, not stored.
        const real = /^\d{4}-\d{2}-\d{2}$/u.test(value) && !Number.isNaN(Date.parse(value));
        if (!real || new Date(value).toISOString().slice(0, 10) !== value) {
          throw new Error(
            `${catalog.name} ${catalogEntryKey(catalog, row)}: no date in "${value}"`,
          );
        }
        return dateNumber(value);
      };
      const rowFrom = from === -1 ? "" : (row[from] ?? "");
      const rowUntil = until === -1 ? "" : (row[until] ?? "");
      return {
        catalog: catalog.name,
        key: catalogEntryKey(catalog, row),
        sourceId,
        fields: catalogEntryFields(catalog, row),
        validFrom: date(rowFrom || catalogFrom),
        validUntil: rowUntil ? date(rowUntil) : IN_FORCE_UNTIL,
      };
    });
  });
}

/** The whole Phase 0 corpus from `docs/sat-md`'s files. */
export function buildCorpus(files: SatMarkdownFiles): Corpus {
  const sources = JSON.parse(files.read("sources.json")) as SatSourceManifest;
  const errorMatrix = JSON.parse(files.read("matriz-de-errores-cfdi-4.0.json")) as SatErrorMatrix;
  const catalogs = JSON.parse(files.read("catalogos-cfdi-4.0.json")) as SatCatalogSet;
  const library = buildSatLibrary({
    markdown: files.read,
    sources,
    records: { errorMatrix, catalogs },
  });
  const guide = (id: "anexo20" | "pagos" | "rmf" | "cff", slug: string) => {
    const document = library.documents.find((candidate) => candidate.slug === slug);
    if (!document) throw new Error(`SAT document ${slug} is missing`);
    return { document, row: sourceRow(id, guideTitle(document), sources[id]) };
  };
  const anexo20 = guide("anexo20", "anexo-20-guia-de-llenado-cfdi");
  const pagos = guide("pagos", "complemento-pagos-guia-de-llenado");
  const rmf = guide("rmf", "resolucion-miscelanea-fiscal-2026");
  const cff = guide("cff", "codigo-fiscal-de-la-federacion");
  // The CFDI documents' names only: the RMF's and the CFF's words would rejoin other wrapped names
  // in the guides, and change their passage keys.
  const vocabulary = nameVocabulary(
    library.documents
      .filter((document) => document !== rmf.document && document !== cff.document)
      .map((document) => document.markdown),
  );
  const catalogTitle = "Catálogos del CFDI 4.0 (catCFDI)";
  return {
    sources: [
      anexo20.row,
      pagos.row,
      sourceRow("matrix", errorMatrix.title, sources.matrix),
      sourceRow("catalogs", catalogTitle, sources.catalogs),
      rmf.row,
      cff.row,
    ],
    passages: [
      ...guidePassages(anexo20.document, anexo20.row.id, anexo20.row.validFrom, vocabulary),
      ...guidePassages(pagos.document, pagos.row.id, pagos.row.validFrom, vocabulary),
      ...errorCodePassages(errorMatrix),
      ...rmfPassages(rmf.document),
      ...cffPassages(cff.document, cff.row.validFrom),
    ],
    errorCodes: errorMatrix.codes.map((row) => ({
      code: row.code,
      sourceId: SOURCES.matrix.id,
      node: row.element,
      attribute: row.attribute,
      validation: row.validation,
      message: row.message,
    })),
    catalogEntries: catalogEntryRows(catalogs),
  };
}

/** A D1 `passages` row: what AI Search holds under `key`, and when it applies. */
export type PassageRecord = {
  readonly key: string;
  readonly sourceId: string;
  readonly heading: string;
  readonly sha256: string;
  /** The body uploaded; null in a row D1 recorded before it kept bodies. */
  readonly body: string | null;
  readonly kind: string | null;
  readonly validFrom: number;
  readonly validUntil: number;
};

export function passageRecord(passage: Passage): PassageRecord {
  return {
    key: passage.key,
    sourceId: passage.sourceId,
    heading: passage.heading,
    sha256: passage.sha256,
    body: passage.body,
    kind: passage.metadata.kind,
    validFrom: passage.metadata.valid_from,
    validUntil: passage.metadata.valid_until,
  };
}

/**
 * The key a superseded passage moves to: `<source>/<anchor>.<valid_from>.md`. No anchor ends in
 * `.` and eight digits (a regla number's parts are short: `regla-2.7.1.21`), so the key cannot
 * meet a current one, and the date its version started makes it unique.
 */
export function versionedKey(key: string, validFrom: number) {
  return key.replace(/\.md$/u, `.${validFrom}.md`);
}

/**
 * The D1 records to write when some items did not finish indexing (stuck, or still indexing when
 * the wait ran out), so a run records what it did index instead of nothing. An unfinished current
 * passage keeps the record an earlier run wrote, or none, so the next run uploads it again; a
 * superseded copy this run made from that record is left out with it, as a run that stopped before
 * D1 would leave it. Every other record is written, superseded ones included: their text would
 * otherwise be lost, and the next run repairs a stuck copy from D1's record.
 */
export function settledRecords(
  records: readonly PassageRecord[],
  recorded: ReadonlyMap<string, PassageRecord>,
  unfinished: ReadonlySet<string>,
): PassageRecord[] {
  const reverted = new Map<string, PassageRecord | undefined>();
  for (const record of records) {
    if (record.validUntil === IN_FORCE_UNTIL && unfinished.has(record.key)) {
      reverted.set(record.key, recorded.get(record.key));
    }
  }
  const madeFromReverted = new Set(
    [...reverted.values()].flatMap((earlier) =>
      earlier ? [versionedKey(earlier.key, earlier.validFrom)] : [],
    ),
  );
  return records.flatMap((record) => {
    if (reverted.has(record.key)) {
      const earlier = reverted.get(record.key);
      return earlier ? [earlier] : [];
    }
    return madeFromReverted.has(record.key) && !recorded.has(record.key) ? [] : [record];
  });
}

/** The day before a `YYYYMMDD` date: the last day a version applies when the next starts on it. */
export function dayBefore(date: number) {
  const day = new Date(Date.parse(isoDate(date)) - 86_400_000);
  return dateNumber(day.toISOString());
}

/** A superseded passage: the item to copy its body from, and its record under the versioned key. */
export type Supersession = {
  /** The current item, which still holds the old body. */
  readonly from: { readonly id: string; readonly key: string };
  readonly record: PassageRecord;
};

/** An AI Search item as the Items listing returns it. */
export type RemoteItem = {
  readonly id: string;
  readonly key: string;
  readonly status?: string;
  /** What AI Search will do with the item next; `null` when it will do nothing. */
  readonly next_action?: string | null;
};

/**
 * An item AI Search will never finish indexing: one that failed (`error`), or one `outdated` with
 * `next_action: null` (left so after a `workers_ai_timeout_error`, 2026-10-25). Uploading the same
 * key again does not change it; only deleting it and uploading again does. A listing without
 * `next_action` marks no `outdated` item stuck: such an item may still be re-indexing.
 */
export function stuckItem(item: RemoteItem) {
  return item.status === "error" || (item.status === "outdated" && item.next_action === null);
}

export type IngestionPlan = {
  /** Stuck items to delete before the uploads, with their keys. */
  readonly repair: readonly { readonly id: string; readonly key: string }[];
  /** Copies of superseded passages to upload first, each from the item that still holds it. */
  readonly supersede: readonly Supersession[];
  readonly upload: readonly Passage[];
  /** Remote item ids to delete, with their keys. */
  readonly remove: readonly { readonly id: string; readonly key: string }[];
  readonly unchanged: number;
  /** The source versions the new ones replace, each ending the day before its successor. */
  readonly sourceVersions: readonly SourceRow[];
  /** D1 `passages` once the plan has run: the current passages and every superseded one. */
  readonly records: readonly PassageRecord[];
};

/**
 * What to change in AI Search and D1 (SPEC.md, "Versions").
 *
 * A passage whose text changed and whose new text starts later than the recorded one (a new
 * version of its source, an amended RMF regla) keeps its old text under its versioned key, valid
 * until the day before the new text starts. A passage a new version of its source (a new hash, a
 * later `valid_from`) drops keeps its text the same way, until the day before that version. A
 * passage whose text is the same keeps the day it first applied. Superseded passages already
 * recorded stay. Any other change (the same version re-split) replaces passages in place.
 *
 * Then: delete every stuck item first (`stuckItem`), copying a superseded passage's text out of
 * it before; upload a passage that is new, changed since the hash D1 recorded, missing from the
 * instance, or stuck; delete every other item no record has.
 */
export function ingestionPlan(input: {
  readonly passages: readonly Passage[];
  readonly sources: readonly SourceRow[];
  /** D1 `sources`, the versions in force at the last run. */
  readonly recordedSources: readonly SourceRow[];
  /** D1 `passages` by item key, current and superseded. */
  readonly recorded: ReadonlyMap<string, PassageRecord>;
  /** The instance's items. */
  readonly items: readonly RemoteItem[];
}): IngestionPlan {
  const stuck = input.items.filter(stuckItem);
  const healthy = input.items.filter((item) => !stuckItem(item));
  const indexed = new Map(healthy.map((item) => [item.key, item]));
  /** Every item by key: a stuck one still holds its body. */
  const stored = new Map(input.items.map((item) => [item.key, item]));
  const recordedSources = new Map(input.recordedSources.map((row) => [row.id, row]));
  const sourceIds = new Set(input.sources.map((row) => row.id));
  const byKey = new Map(input.passages.map((passage) => [passage.key, passage]));

  const sourceVersions: SourceRow[] = [];
  /** A source's new version by id: the day it starts. */
  const newVersions = new Map<string, number>();
  for (const source of input.sources) {
    const previous = recordedSources.get(source.id);
    if (previous && previous.sha256 !== source.sha256 && source.validFrom > previous.validFrom) {
      sourceVersions.push({ ...previous, validUntil: dayBefore(source.validFrom) });
      newVersions.set(source.id, source.validFrom);
    }
  }

  const supersede: Supersession[] = [];
  const superseded: PassageRecord[] = [];
  /** The first day an unchanged passage applied, as an earlier run recorded it. */
  const firstDay = new Map<string, number>();
  for (const record of input.recorded.values()) {
    if (!sourceIds.has(record.sourceId)) continue;
    if (record.validUntil !== IN_FORCE_UNTIL) {
      superseded.push(record);
      // A stuck copy is copied again from itself before the repair deletes it.
      const item = stored.get(record.key);
      if (item && stuckItem(item)) supersede.push({ from: { id: item.id, key: item.key }, record });
      continue;
    }
    const next = byKey.get(record.key);
    if (next?.sha256 === record.sha256) {
      firstDay.set(record.key, record.validFrom);
      continue;
    }
    // The first day of the text that replaces it: the new passage's own (an amended RMF regla's
    // DOF date), or, for a dropped passage, its source's new version.
    const start = next ? next.metadata.valid_from : newVersions.get(record.sourceId);
    // No later start (the same version re-split): replaced in place.
    if (start === undefined || start <= record.validFrom) continue;
    const old: PassageRecord = {
      ...record,
      key: versionedKey(record.key, record.validFrom),
      validUntil: dayBefore(start),
    };
    if (old.key.length > ITEM_KEY_MAX) throw new Error(`${old.key} is longer than ${ITEM_KEY_MAX}`);
    superseded.push(old);
    // Copied on an earlier run that stopped before D1: the current item may already hold the new
    // text, and the copy is the old one.
    if (indexed.has(old.key)) continue;
    // A stuck copy from that run still holds the old text; else the current item does.
    const from = stored.get(old.key) ?? stored.get(record.key);
    if (!from) throw new Error(`${record.key} is not in AI Search; its old text cannot be kept`);
    supersede.push({ from: { id: from.id, key: from.key }, record: old });
  }

  const current = input.passages.map((passage): Passage => {
    const first = firstDay.get(passage.key);
    return first === undefined || first === passage.metadata.valid_from
      ? passage
      : { ...passage, metadata: { ...passage.metadata, valid_from: first } };
  });
  const upload = current.filter((passage) => {
    const record = input.recorded.get(passage.key);
    return (
      !indexed.has(passage.key) ||
      record?.sha256 !== passage.sha256 ||
      record.validFrom !== passage.metadata.valid_from ||
      record.validUntil !== passage.metadata.valid_until
    );
  });
  const records = [...current.map(passageRecord), ...superseded];
  const kept = new Set(records.map((record) => record.key));
  return {
    supersede,
    upload,
    repair: stuck.map(({ id, key }) => ({ id, key })),
    remove: healthy.filter((item) => !kept.has(item.key)).map(({ id, key }) => ({ id, key })),
    unchanged: input.passages.length - upload.length,
    sourceVersions,
    records,
  };
}
